/* io_getevents() */
/* Header: <libaio.h> */

aio_context_t ctx_id;
long min_events = 1;
long max_events = 10;
struct io_event events[10];

/* Wait indefinitely */
long num_read = io_getevents(ctx_id,
                             min_events,
                             max_events,
                             events,
                             NULL);

/* Wait for 500ms */
struct timespec timeout_500ms = {.tv_sec = 0, .tv_nsec = 500000000};
num_read = io_getevents(ctx_id,
                        1,
                        5,
                        events,
                        &timeout_500ms);
